DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Facing$q$, 2, 9),
    ($q$Machining - Rough Milling$q$, 5, 9),
    ($q$Machining - Bulk Milling$q$, 5, 9),
    ($q$Machining - Fine Finish Milling$q$, 10, 9),
    ($q$Machining - Contouring$q$, 7, 9),
    ($q$Machining - Perimeter Milling$q$, 7, 9),
    ($q$Machining - Slot Milling$q$, 3, 9),
    ($q$Machining - Center Drilling$q$, 3, 9),
    ($q$Machining - Chamfering$q$, 5, 9),
    ($q$Machining - Filleting$q$, 5, 9),
    ($q$Machining - Groove Milling$q$, 5, 9)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1031: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
